import boto3
from langchain_core.tools import tool

_s3 = boto3.client("s3")


@tool
def move_objects_by_extension(bucket: str, src_prefix: str, dst_prefix: str, ext: str, dry_run: bool = True) -> dict:
    if not src_prefix.endswith("/"):
        src_prefix += "/"
    if not dst_prefix.endswith("/"):
        dst_prefix += "/"
    if not ext.startswith("."):
        ext = "." + ext
    pg = _s3.get_paginator("list_objects_v2")
    hits = []
    for page in pg.paginate(Bucket=bucket, Prefix=src_prefix):
        for o in page.get("Contents", []):
            k = o["Key"]
            if k.lower().endswith(ext.lower()):
                hits.append(k)
    moved = []
    failed = []
    if dry_run:
        return {"dry_run": True, "matches": hits, "moved": moved, "failed": failed}
    for k in hits:
        nk = dst_prefix + k[len(src_prefix):]
        if nk == k:
            continue
        try:
            _s3.copy_object(
                Bucket=bucket,
                Key=nk,
                CopySource={"Bucket": bucket, "Key": k},
            )
            _s3.delete_object(Bucket=bucket, Key=k)
            moved.append(nk)
        except Exception as e:
            failed.append({"key": k, "error": str(e)})
    return {"dry_run": False, "matches": hits, "moved": moved, "failed": failed}
